// Variable-order sequence model. Find the longest context matching the most
// recent elements (ctx[0] is the oldest, ctx[order-1] the most recent), then
// draw the next category from its cumulative table (compare a uint16 random
// number against cdf[]). Entries are sorted longest context first; the last
// entry has order 0 and always matches.
typedef struct {
    uint8_t order;
    uint8_t ctx[BUDGIE_MAX_ORDER > 0 ? BUDGIE_MAX_ORDER : 1];
    uint16_t cdf[BUDGIE_N_CATEGORIES];
} budgie_context_t;

